// Native complication geometry from the same paths that generate axo.riv. No bitmap tinting.
import { readFile, writeFile } from "node:fs/promises";
import { isAbsolute } from "node:path";
import { mascotMarkGeometry } from "./mascot.ts";

const geometry = mascotMarkGeometry();
const number = (value: number) => String(Number(value.toFixed(6)));
const point = (value: { x: number; y: number }) => `CGPoint(x: ${number(value.x)}, y: ${number(value.y)})`;
const lines = [
  "// Generated by //packages/axo-mascot:export_vector from mascot.ts. Do not edit.",
  "import SwiftUI", "", "enum AxoMascotGeometry {",
  `  static let bounds = CGRect(x: ${geometry.bounds.x}, y: ${geometry.bounds.y}, width: ${geometry.bounds.width}, height: ${geometry.bounds.height})`,
  "  static let ink: Path = {", "    var ink = Path()",
];
for (const [index, path] of geometry.paths.entries()) {
  const name = `outline${index}`;
  lines.push(`    var ${name} = Path()`, `    ${name}.move(to: ${point(path.vertices[0]!.at)})`);
  for (let i = 1; i < path.vertices.length; i++) {
    const a = path.vertices[i - 1]!;
    const b = path.vertices[i]!;
    lines.push(`    ${name}.addCurve(to: ${point(b.at)}, control1: ${point(a.out)}, control2: ${point(b.in)})`);
  }
  if (path.closed) {
    const a = path.vertices.at(-1)!;
    const b = path.vertices[0]!;
    lines.push(`    ${name}.addCurve(to: ${point(b.at)}, control1: ${point(a.out)}, control2: ${point(b.in)})`, `    ${name}.closeSubpath()`);
  }
  lines.push(`    ink.addPath(${name}.strokedPath(StrokeStyle(lineWidth: ${path.width}, lineCap: .round, lineJoin: .round)))`);
}
for (const eye of geometry.eyes) {
  lines.push(`    ink.addEllipse(in: CGRect(x: ${eye.x - eye.size / 2}, y: ${eye.y - eye.size / 2}, width: ${eye.size}, height: ${eye.size}))`);
}
lines.push("    return ink", "  }()", "}", "");
const source = lines.join("\n");
if (process.argv.includes("--check")) {
  const file = new URL("../../../apple/AxoMascot/Sources/AxoMascotVector/AxoMascotGeometry.swift", import.meta.url);
  if (await readFile(file, "utf8") !== source) throw new Error("Native mascot geometry is stale; run export_vector");
  console.log("Native mascot geometry matches the Rive source");
} else {
  const output = process.argv[2];
  if (!output || !isAbsolute(output)) throw new Error("Pass an absolute Swift output path");
  await writeFile(output, source);
  console.log("Exported native mascot geometry");
}
